import { html, LitElement, css, nothing } from 'lit';
import { deeplink, pushStateFromComponent } from '../deeplink.js';
import { debounce, updateHash, paramsToHash } from '../utils.js';
import { EVENT_MERCH_SIDENAV_SELECT } from '../constants.js';

export class MerchSidenavList extends LitElement {
    static properties = {
        sidenavListTitle: { type: String },
        label: { type: String },
        deeplink: { type: String, attribute: 'deeplink' },
        selectedText: {
            type: String,
            reflect: true,
            attribute: 'selected-text',
        },
        selectedValue: {
            type: String,
            reflect: true,
            attribute: 'selected-value',
        },
        toggleIconColor: {
            type: Boolean,
            attribute: 'toggle-icon-color',
        },
    };

    static styles = css`
        :host {
            display: block;
            contain: content;
            margin-top: var(--merch-sidenav-list-gap);
        }

        :host h2 {
            color: var(--merch-sidenav-list-title-color);
            font-size: var(--merch-sidenav-list-title-font-size);
            font-weight: var(--merch-sidenav-list-title-font-weight);
            padding: var(--merch-sidenav-list-title-padding);
            line-height: var(--merch-sidenav-list-title-line-height);
            margin: 0;
            text-transform: uppercase;
        }

        :host(:dir(rtl)) h2 {
            text-align: right;
        }

        .right {
            position: absolute;
            inset-inline-end: 0;
        }

        :host(:dir(rtl)) .right {
            right: initial;
            left: 0;
        }
    `;

    constructor() {
        super();
        this.toggleIconColor = false;
        this.handleClickDebounced = debounce(this.handleClick.bind(this));
    }

    selectElement(element, selected = true) {
        element.selected = selected;
        if (element.parentNode.tagName === 'SP-SIDENAV-ITEM') {
            this.selectElement(element.parentNode, false);
        }
        const selectionElement = element.querySelector('.selection');
        selectionElement?.setAttribute('selected', selected);
        const selection = selectionElement?.dataset;
        const iconSrc =
            selected && this.toggleIconColor
                ? selection?.light
                : selection?.dark;
        if (iconSrc) {
            element.querySelector('img')?.setAttribute('src', iconSrc);
        }
        if (selected) {
            this.selectedElement = element;
            this.selectedText = selection?.selectedText || element.label;
            this.selectedValue = element.value;
            setTimeout(() => {
                element.selected = true;
            }, 1);
            this.dispatchEvent(
                new CustomEvent(EVENT_MERCH_SIDENAV_SELECT, {
                    bubbles: true,
                    composed: true,
                    detail: {
                        type: 'sidenav',
                        value: this.selectedValue,
                        elt: this.selectedElement,
                    },
                }),
            );
        }
    }

    markCurrentItem(element) {
        const sidenav = element.closest('sp-sidenav');
        if (!sidenav) return;
        sidenav
            .querySelectorAll('sp-sidenav-item[aria-current]')
            .forEach((currentItem) => {
                currentItem.removeAttribute('aria-current');
            });
        element.setAttribute('aria-current', 'true');
    }

    /**
     * click handler to manage first level items state of sidenav
     * @param {*} param
     */
    handleClick({ target: item }, shouldUpdateHash = true) {
        const { value, parentNode } = item;
        this.selectElement(item);
        this.markCurrentItem(item);
        if (parentNode?.tagName === 'SP-SIDENAV') {
            //swc does not consider, in multilevel, first level as a potential selection
            //and does not close other parents, we'll do that here
            parentNode
                .querySelectorAll(
                    'sp-sidenav-item[expanded],sp-sidenav-item[selected]',
                )
                .forEach((item) => {
                    if (item.value !== value) {
                        item.expanded = false;
                        item.removeAttribute('aria-expanded');
                        this.selectElement(item, false);
                    }
                });
            //additional call to disable previous selection settings
            parentNode
                .querySelectorAll('.selection[selected=true]')
                .forEach((selection) => {
                    const item = selection.parentElement;
                    if (item.value !== value) {
                        this.selectElement(item, false);
                    }
                });
        } else if (parentNode?.tagName === 'SP-SIDENAV-ITEM') {
            const topLevelItems = parentNode
                .closest('sp-sidenav')
                ?.querySelectorAll(':scope > sp-sidenav-item');
            [...topLevelItems]
                .filter((item) => item !== parentNode)
                .forEach((item) => {
                    item.expanded = false;
                    item.removeAttribute('aria-expanded');
                });
            parentNode
                .closest('sp-sidenav')
                ?.querySelectorAll('sp-sidenav-item[selected]')
                .forEach((item) => {
                    if (item.value !== value) {
                        this.selectElement(item, false);
                    }
                });
        }
        if (shouldUpdateHash) {
            pushStateFromComponent(this, value);
        }
    }

    /**
     * leaf level item selection handler
     * @param {*} event
     */
    selectionChanged(event) {
        const {
            target: { value, parentNode },
        } = event;
        this.selectElement(
            this.querySelector(`sp-sidenav-item[value="${value}"]`),
        );
        pushStateFromComponent(this, value);
    }

    startDeeplink() {
        this.stopDeeplink = deeplink((params) => {
            const value = params[this.deeplink] ?? 'all';
            let element = this.querySelector(
                `sp-sidenav-item[value="${value}"]`,
            );
            // fallback for invalid filter
            if (!element) {
                element = this.querySelector('sp-sidenav-item:first-child');
                updateHash(this.deeplink, element.value);
            }

            this.updateComplete.then(() => {
                if (element.firstElementChild?.tagName === 'SP-SIDENAV-ITEM') {
                    element.expanded = true;
                    element.setAttribute('aria-expanded', 'true');
                }
                if (element.parentNode?.tagName === 'SP-SIDENAV-ITEM') {
                    element.parentNode.expanded = true;
                    element.parentNode.setAttribute('aria-expanded', 'true');
                }
                this.handleClick(
                    { target: element },
                    !!window.location.hash.includes('category'),
                );
            });
        });
    }

    connectedCallback() {
        super.connectedCallback();
        this.addEventListener('click', this.handleClickDebounced);
        this.updateComplete.then(() => {
            if (!this.deeplink) return;
            paramsToHash(['filter', 'single_app']);
            this.startDeeplink();
        });
    }

    disconnectedCallback() {
        super.disconnectedCallback();
        this.removeEventListener('click', this.handleClickDebounced);
        this.stopDeeplink?.();
    }

    render() {
        return html`<div
            aria-label="${this.label}"
            @change="${(e) => this.selectionChanged(e)}"
        >
            ${this.sidenavListTitle
                ? html`<h2>${this.sidenavListTitle}</h2>`
                : nothing}
            <slot></slot>
        </div>`;
    }
}

customElements.define('merch-sidenav-list', MerchSidenavList);

function normalizePath(path) {
    if (!path) return '/';
    const pathname = path.startsWith('http') ? new URL(path).pathname : path;
    const stripped = pathname.split('#')[0].split('?')[0];
    if (stripped.length > 1 && stripped.endsWith('/')) return stripped.slice(0, -1);
    return stripped;
}

function humanize(segment) {
    return segment.replace(/[-_]/g, ' ').replace(/\b\w/g, (char) => char.toUpperCase());
}

function createNode(path, title) {
    return {
        path,
        title,
        children: new Map(),
    };
}

function toFolderPath(path) {
    if (path === '/') return path;
    return path.endsWith('/') ? path : `${path}/`;
}

function buildTree(data) {
    const docsRoot = createNode('/docs', 'Docs');
    const filtered = data
        .map((entry) => ({
            ...entry,
            path: normalizePath(entry.path),
        }))
        .filter((entry) => entry.path === '/docs' || entry.path.startsWith('/docs/'));

    filtered.forEach((entry) => {
        const segments = entry.path
            .replace(/^\/docs\/?/, '')
            .split('/')
            .filter(Boolean);

        if (!segments.length) {
            docsRoot.title = entry.title || docsRoot.title;
            return;
        }

        let current = docsRoot;
        let currentPath = '/docs';

        segments.forEach((segment, index) => {
            currentPath = `${currentPath}/${segment}`;
            if (!current.children.has(segment)) {
                current.children.set(segment, createNode(toFolderPath(currentPath), humanize(segment)));
            }

            const node = current.children.get(segment);
            if (index === segments.length - 1) {
                node.title = entry.title || node.title;
                node.path = entry.path;
            }

            current = node;
        });
    });

    return docsRoot;
}

function sortNodes(node) {
    const entries = [...node.children.entries()].sort((a, b) => a[1].title.localeCompare(b[1].title));
    node.children = new Map(entries);
    node.children.forEach((child) => sortNodes(child));
}

function renderBranch(node, currentPath) {
    const ul = document.createElement('ul');

    node.children.forEach((child) => {
        const li = document.createElement('li');
        const link = document.createElement('a');
        const normalizedChildPath = normalizePath(child.path);
        const inPath = currentPath === normalizedChildPath || currentPath.startsWith(`${normalizedChildPath}/`);
        const hasChildren = child.children.size > 0;
        const href = hasChildren ? toFolderPath(normalizedChildPath) : child.path;

        link.textContent = child.title;
        link.href = href;
        if (currentPath === child.path) {
            link.setAttribute('aria-current', 'page');
        }

        li.append(link);

        if (hasChildren) {
            const button = document.createElement('button');
            button.className = 'sidenav-toggle';
            button.type = 'button';
            button.setAttribute('aria-label', `Expand ${child.title}`);
            button.setAttribute('aria-expanded', inPath ? 'true' : 'false');
            button.textContent = '▸';

            const branch = renderBranch(child, currentPath);
            branch.classList.add('sidenav-branch');
            if (inPath) {
                li.classList.add('is-open');
            }

            button.addEventListener('click', () => {
                const isOpen = li.classList.toggle('is-open');
                button.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
            });

            li.append(button, branch);
        }

        ul.append(li);
    });

    return ul;
}

async function fetchIndexData() {
    const response = await fetch('/query-index.json');
    if (!response.ok) throw new Error('Could not fetch query index');
    const payload = await response.json();
    if (!payload || !Array.isArray(payload.data)) return [];
    return payload.data;
}

export default async function decorate(block) {
    const currentPath = normalizePath(window.location.pathname);
    const title = document.createElement('a');
    const studioButton = document.createElement('a');
    title.className = 'sidenav-title';
    title.href = '/docs/';
    title.textContent = 'Docs';
    studioButton.className = 'sidenav-studio-button';
    studioButton.href = '/studio.html';
    studioButton.textContent = 'To studio';
    block.append(title);

    try {
        const data = await fetchIndexData();
        const tree = buildTree(data);
        sortNodes(tree);

        title.textContent = tree.title || 'Docs';
        block.append(renderBranch(tree, currentPath));
    } catch (e) {
        const message = document.createElement('p');
        message.className = 'sidenav-error';
        message.textContent = 'Navigation is unavailable.';
        block.append(message);
    }

    block.append(studioButton);
}
